func (i *Index) updateShardStatus(ctx, shardName, targetStatus string) error {
    isOwner := false
    if err := i.schemaReader.Read(..., func(_ *models.Class, state *sharding.State) error {
        if state != nil { isOwner = state.IsLocalShard(shardName) }
        return nil
    }); err != nil { return err }
    if !isOwner {
        return nil          // ← 不存在的分片：静默成功（nil），无 404 无校验
    }
    shard, release, err := i.getOrInitShard(ctx, shardName) ...
    return shard.UpdateStatus(targetStatus, statusReasonManualUpdate)  // 真分片才走到状态枚举校验 → 422
}

